void uCharacterEditBase::move() {
    mIsComplete = true;
    switch (mMode) {
        case MODE_LOAD_ARC:
        {
            if (moveLoadArc()) {
                mMode = MODE_LOAD_UNIT;
                mProc = 0;
                if (mpModel != nullptr) {
                    mpModel->requestCommandCacheReset();
                }
            } else {
                if (mpModel != nullptr) {
                    mpModel->requestCommandCacheReset();
                }
            }
            break;
        }
        case MODE_LOAD_UNIT:
        {
            moveLoadUnit();
            if (mpModel != nullptr) {
                mpModel->requestCommandCacheReset();
            }
            break;
        }
        case MODE_MAIN:
        {
            moveMain();
            if (mpModel != nullptr) {
                mpModel->requestCommandCacheReset();
            }
            break;
        }
        case MODE_END:
        {
            moveEnd();
            if (mpModel != nullptr) {
                mpModel->requestCommandCacheReset();
            }
            break;
        }
        default:
        {
            if (mpModel != nullptr) {
                mpModel->requestCommandCacheReset();
            }
            break;
        }
    }
}

